package dev.astralreach.hytale;
import com.hypixel.hytale.component.*;import com.hypixel.hytale.component.query.Query;import com.hypixel.hytale.component.system.EntityEventSystem;import com.hypixel.hytale.server.core.event.events.ecs.*;import com.hypixel.hytale.server.core.entity.entities.Player;import com.hypixel.hytale.server.core.universe.PlayerRef;import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;import dev.astralreach.core.*;import java.util.*;import static dev.astralreach.hytale.RocketRegistry.Cell;
/** A station's permanent frame routes power; real loaded devices store and consume it. */
final class StationSystems{
 static final Set<String>TYPES=Set.of("AR_SolarArray","AR_StationBattery","AR_StationLifeSupport");
 static StationSystemsRegistry data(Store<EntityStore>s){return s.getResource(AstralReachPlugin.systemsType);}
 static StationRegistry.Station station(Store<EntityStore>s,Cell at){if(!StationService.world(s))return null;for(var st:StationService.data(s).stations.values())if(st.layout.contains(at.x(),at.y(),at.z()))return st;return null;}
 static boolean granted(Store<EntityStore>s,Cell at){var d=data(s).devices.get(at);return d!=null&&d.granted;}
 static boolean inHull(StationRegistry.Station st,org.joml.Vector3d h){if(st.layout.insideConcourse(h.x,h.y,h.z))return true;for(int i=0;i<StationLayout.PORTS;i++){var p=st.layout.port(i);if(Math.abs(h.x-(p.x()+.5))<2.4&&h.y>p.y()+.6&&h.y<p.y()+5.8&&h.z>p.z()-2&&h.z<st.layout.z()-100)return true;}return false;}
 static boolean suppliesHull(Store<EntityStore>s,Cell at,org.joml.Vector3d h){var st=station(s,at);return st!=null&&NativeBlocks.base(NativeBlocks.get(s.getExternalData().getWorld(),at)).equals("AR_StationLifeSupport")&&inHull(st,h);}
 record Status(double charge,int batteries,int panels,int consumers,boolean sunlit){}
 static Status status(Store<EntityStore>s,StationRegistry.Station st){double charge=0;int batteries=0,panels=frame(s,st)?1:0,consumers=0;for(var e:data(s).devices.entrySet()){var at=e.getKey();var d=e.getValue();if(station(s,at)!=st||!loaded(s,at,d))continue;if(d.type.equals("AR_StationBattery")){batteries++;charge+=d.charge;}else if(d.type.equals("AR_SolarArray"))panels++;else{var oxygen=OxygenService.data(s).diffusers.get(at);if(oxygen!=null&&oxygen.enabled&&oxygen.oxygen()>0)consumers++;}}return new Status(charge,batteries,panels,consumers,StationPower.sunlit(System.currentTimeMillis()/1000d));}
 private static boolean loaded(Store<EntityStore>s,Cell at,StationSystemsRegistry.Device d){var w=s.getExternalData().getWorld();return NativeBlocks.ticking(w,at)&&NativeBlocks.base(NativeBlocks.get(w,at)).equals(d.type);}
 private static boolean frame(Store<EntityStore>s,StationRegistry.Station st){if(st.shellVersion!=2)return false;var w=s.getExternalData().getWorld();for(var part:st.layout.shell())if(part.item().equals("AR_StationConcourse")&&(part.state().equals("West")||part.state().equals("East"))){var at=StationService.cell(part.at());if(NativeBlocks.ticking(w,at)&&NativeBlocks.base(NativeBlocks.get(w,at)).equals(part.item()))return true;}return false;}
 static void tick(Store<EntityStore>s,float dt){var registry=data(s);registry.elapsed+=Math.max(0,Math.min(1,dt));if(registry.elapsed<1)return;double elapsed=Math.min(1,registry.elapsed);registry.elapsed=0;for(var d:registry.devices.values()){d.previous=d.granted;d.granted=false;}if(!StationService.world(s))return;
  for(var st:StationService.data(s).stations.values()){var batteries=new ArrayList<StationSystemsRegistry.Device>();var loads=new ArrayList<StationSystemsRegistry.Device>();int panels=frame(s,st)?1:0;double charge=0;for(var e:registry.devices.entrySet()){var d=e.getValue();if(station(s,e.getKey())!=st||!loaded(s,e.getKey(),d))continue;if(d.type.equals("AR_StationBattery")){batteries.add(d);charge+=d.charge;}else if(d.type.equals("AR_SolarArray"))panels++;else{var o=OxygenService.data(s).diffusers.get(e.getKey());if(o!=null&&o.enabled&&o.oxygen()>0)loads.add(d);}}
   var budget=StationPower.advance(charge,batteries.size(),panels,loads.size(),elapsed,StationPower.sunlit(System.currentTimeMillis()/1000d));for(int i=0;i<budget.supplied();i++)loads.get(i).granted=true;double remaining=budget.stored();for(var b:batteries){b.charge=Math.min(StationPower.CAPACITY,remaining);remaining-=b.charge;}
  }
  for(var e:registry.devices.entrySet()){var d=e.getValue();if(!loaded(s,e.getKey(),d))continue;if(d.granted&&!d.previous)for(var p:s.getExternalData().getWorld().getPlayerRefs()){var r=p.getReference();if(r!=null&&r.isValid()&&r.getStore()==s&&RocketService.near(s,r,e.getKey()))RocketService.cue(s,p,"AR_station_power",e.getKey());}if(d.type.equals("AR_StationBattery"))NativeBlocks.stateOf(s.getExternalData().getWorld(),e.getKey(),d.type,d.charge>StationPower.CAPACITY*.66?"Full":d.charge>0?"Charged":"default");}
 }
 static void use(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,Cell at){try{var root=NativeBlocks.root(s.getExternalData().getWorld(),at);if(root!=null)at=root;if(!RocketService.near(s,r,at))throw new IllegalArgumentException("Stand beside the equipment.");String id=NativeBlocks.base(NativeBlocks.get(s.getExternalData().getWorld(),at));if(id.equals("AR_StationTracker")){StationTrackerPage.open(s,r,p);return;}if(!TYPES.contains(id))return;var st=StationService.docked(s,r,p);if(station(s,at)!=st)throw new IllegalArgumentException("Use equipment inside your docked station plot.");StationSystemsPage.open(s,r,p,at);}catch(IllegalArgumentException ex){AstralReachPlugin.message(p,ex.getMessage());}}
 static final class Placement extends EntityEventSystem<EntityStore,PlaceBlockEvent>{Placement(){super(PlaceBlockEvent.class);}@Override public Query<EntityStore>getQuery(){return PlayerRef.getComponentType();}@Override public void handle(int i,ArchetypeChunk<EntityStore>c,Store<EntityStore>s,CommandBuffer<EntityStore>b,PlaceBlockEvent e){if(e.isCancelled()||e.getItemInHand()==null||!TYPES.contains(e.getItemInHand().getItemId()))return;String id=e.getItemInHand().getItemId();var p=c.getComponent(i,PlayerRef.getComponentType());var v=e.getTargetBlock();var at=new Cell(v.x,v.y,v.z);var st=station(s,at);if(st==null||!st.allows(p.getUuid())){e.setCancelled(true);AstralReachPlugin.message(p,"Place station utilities inside your own or an invited orbital build plot.");return;}s.getExternalData().getWorld().execute(()->{if(NativeBlocks.base(NativeBlocks.get(s.getExternalData().getWorld(),at)).equals(id))data(s).devices.putIfAbsent(at,new StationSystemsRegistry.Device(p.getUuid(),id));});}}
 static final class Breaking extends EntityEventSystem<EntityStore,BreakBlockEvent>{Breaking(){super(BreakBlockEvent.class);}@Override public Query<EntityStore>getQuery(){return PlayerRef.getComponentType();}@Override public void handle(int i,ArchetypeChunk<EntityStore>c,Store<EntityStore>s,CommandBuffer<EntityStore>b,BreakBlockEvent e){if(e.isCancelled())return;var v=e.getTargetBlock();var at=new Cell(v.x,v.y,v.z);var d=data(s).devices.get(at);if(d==null)return;s.getExternalData().getWorld().execute(()->{if(!NativeBlocks.base(NativeBlocks.get(s.getExternalData().getWorld(),at)).equals(d.type))data(s).devices.remove(at,d);});}}
 private StationSystems(){}
}
